window.__POLYGON_SCRIPT_V2_PARTS__.push("          els.contextMenu.classList.add('is-open');\n          els.contextMenu.style.left = `${Math.min(window.innerWidth - 238, event.clientX)}px`;\n          els.contextMenu.style.top = `${Math.min(window.innerHeight - 250, event.clientY)}px`;\n        });\n\n        els.mapSurface.addEventListener('click', event => {\n          closeContextMenu();\n          if (applyMapAction(event)) return;\n          if (!event.target.closest('.unit-marker')) {\n            state.selectedUnitId = null;\n            renderUnits();\n            renderInspector();\n            if (state.workspace === 'unit-editor') renderWorkspace();\n          }\n        });\n        els.mapSurface.addEventListener('contextmenu', openMapContextMenu);\n\n        els.contextMenu.addEventListener('click', event => {\n          const unitButton = event.target.closest('[data-unit-context-action]');\n          if (unitButton) {\n            closeContextMenu();\n            const action = unitButton.dataset.unitContextAction;\n            if (action === 'edit') { setWorkspaceMode('unit-editor'); togglePanel('left', false); }\n            else handleUnitAction(action);\n            return;\n          }\n          const button = event.target.closest('[data-context-action]');\n          if (button) handleContextAction(button.dataset.contextAction);\n        });\n\n        els.collapseLeft.addEventListener('click', () => togglePanel('left'));\n        els.collapseRight.addEventListener('click', () => togglePanel('right'));\n        bindResizer(els.leftResizer, 'left');\n        bindResizer(els.rightResizer, 'right');\n\n        els.runButton.addEventListener('click', () => {\n          if (state.simulation === 'running') setSimulationState('paused');\n          else setSimulationState('running');\n        });\n        els.playButton.addEventListener('click', () => setSimulationState('running'));\n        els.pauseButton.addEventListener('click', () => setSimulationState('paused'));\n        els.resetButton.addEventListener('click', () => resetExperiment({ keepMetadata: true }));\n        els.speedSelect.addEventListener('change', () => {\n          state.speed = Number(els.speedSelect.value);\n          toast(`Скорость: ×${state.speed}`);\n        });\n\n        els.fileButton.addEventListener('click', () => openModal('file'));\n        els.editorsButton.addEventListener('click', () => openModal('editors'));\n        els.viewButton.addEventListener('click', event => {\n          event.stopPropagation();\n          toggleDropdown(els.viewButton, els.viewDropdown);\n        });\n        els.menuButton.addEventListener('click', event => {\n          event.stopPropagation();\n          toggleDropdown(els.menuButton, els.menuDropdown);\n        });\n        els.languageButton.addEventListener('click', () => toast('Переключение языка не входит в этот прототип'));\n\n        els.viewDropdown.addEventListener('change', event => {\n          const input = event.target.closest('[data-layer]');\n          if (input) applyLayer(input.dataset.layer, input.checked);\n        });\n        els.menuDropdown.addEventListener('click', event => {\n          const action = event.target.closest('[data-menu-action]')?.dataset.menuAction;\n          if (action === 'reset-layout') resetLayout();\n          closeDropdowns();\n        });\n\n        els.modalBackdrop.addEventListener('mousedown', event => {\n          if (event.target === els.modalBackdrop) closeModal({ revert: state.modalType === 'unit-details' });\n        });\n        els.modal.addEventListener('click', event => {\n          const modalAction = event.target.closest('[data-unit-modal-action]')?.dataset.unitModalAction;\n          if (modalAction === 'cancel') { closeModal({ revert: true }); return; }\n          if (modalAction === 'done') { state.unitModalSnapshot = null; closeModal(); toast('Настройки юнита применены'); return; }\n          const detailTab = event.target.closest('[data-unit-details-tab]')?.dataset.unitDetailsTab;\n          if (detailTab) { state.unitDetailsTab = detailTab; renderUnitDetailsModal(); return; }\n          const unitAction = event.target.closest('[data-unit-action]')?.dataset.unitAction;\n          if (unitAction) { handleUnitAction(unitAction); return; }\n          const pose = event.target.closest('[data-unit-pose]')?.dataset.unitPose;\n          if (pose) { const unit = ensureUnitDefaults(selectedUnit()); if (unit) { unit.pose = pose; renderUnitDetailsModal(); renderUnits(); renderInspector(); } return; }\n          if (event.target.closest('[data-modal-close]')) {\n            closeModal();\n            return;\n          }\n          const editorButton = event.target.closest('[data-editor-name]');\n          if (editorButton) {\n            updateEditorSelection(editorButton.dataset.editorName);\n            return;\n          }\n          const fileAction = event.target.closest('[data-file-action]')?.dataset.fileAction;\n          if (!fileAction) return;\n          if (fileAction === 'apply-meta') applyFileMetadata();\n          if (fileAction === 'save') exportJson();\n          if (fileAction === 'open') els.jsonFileInput.click();\n          if (fileAction === 'new') {\n            resetExperiment({ silent: true });\n            renderFileModal();\n            toast('Создан новый эксперимент');\n          }\n        });\n        els.modal.addEventListener('input', event => {\n          const field = event.target.closest('[data-unit-detail-field]');\n          if (field && field.dataset.unitDetailField === 'name') updateUnitField(field.dataset.unitDetailField, field.value, { keepModal: true });\n        });\n        els.modal.addEventListener('change', event => {\n          const field = event.target.closest('[data-unit-detail-field]');\n          if (field) updateUnitField(field.dataset.unitDetailField, field.value, { keepModal: true });\n        });\n\n        els.jsonFileInput.addEventListener('change', () => {\n          const file = els.jsonFileInput.files?.[0];\n          if (file) importJson(file);\n          els.jsonFileInput.value = '';\n        });\n\n        els.cancelAction.addEventListener('click', cancelMapAction);\n\n        document.addEventListener('click', event => {\n          if (!event.target.closest('.dropdown-anchor')) closeDropdowns();\n          if (!event.target.closest('#contextMenu') && !event.target.closest('#mapSurface')) closeContextMenu();\n        });\n        document.addEventListener('keydown', event => {\n          if (event.key === 'Escape') {\n            if (state.mapAction) cancelMapAction();\n            else if (els.modalBackdrop.classList.contains('is-open')) closeModal({ revert: state.modalType === 'unit-details' });\n            else {\n              closeDropdowns();\n              closeContextMenu();\n            }\n          }\n        });\n      }\n\n      function assert(condition, message) {\n        if (!condition) throw new Error(message);\n      }\n\n      async function runSelfTest() {\n        try {\n          setWorkspaceMode('map-editor', { silent: true });\n          assert(state.workspace === 'map-editor', 'Не переключился редактор карты');\n          setSimulationState('running', { silent: true });\n          setWorkspaceMode('unit-editor', { silent: true });\n          assert(state.simulation === 'paused', 'Редактор не поставил симуляцию на паузу');\n          selectUnit('unit-1', { silent: true });\n          assert(els.rightPanelTitle.textContent === 'Стрелок 1', 'Инспектор не показал юнита');\n          assert(!!els.leftPanelContent.querySelector('[data-unit-editor-toolbar]'), 'Нет компактной панели редактора юнита');\n          assert(els.leftPanelContent.querySelectorAll('[data-unit-pose]').length === 3, 'Нет трёх кнопок положения тела');\n          openModal('unit-details');\n          assert(els.modal.classList.contains('modal--unit'), 'Не открылось окно подробных настроек');\n          assert(els.modal.querySelectorAll('[data-unit-details-tab]').length === 4, 'Неверное число вкладок подробных настроек');\n          closeModal();\n          togglePanel('left', true);\n          assert(els.leftPanel.classList.contains('is-collapsed'), 'Левая панель не свернулась');\n          togglePanel('left', false);\n          openModal('file');\n          assert(els.modalBackdrop.classList.contains('is-open') && els.modal.textContent.includes('Новый эксперимент'), 'Окно Файл не открылось');\n          closeModal();\n          openModal('editors');\n          assert(els.modal.textContent.includes('Профили маршрута'), 'Окно Редакторы не открылось');\n          closeModal();\n          setWorkspaceMode('program', { silent: true });\n          openMapContextMenu(600, 300);\n          assert(els.contextMenu.querySelectorAll('[data-context-action]').length === 3, 'Контекстное меню Программы неверно');\n          closeContextMenu();\n          applyLayer('grid', false);\n          assert(els.mapViewport.classList.contains('hide-grid'), 'Слой сетки не переключился');\n          applyLayer('grid', true);\n          state.selectedUnitId = null;\n          renderUnits();\n          renderInspector();\n          setWorkspaceMode('program', { silent: true });\n          els.selfTestResult.dataset.status = 'pass';\n          els.selfTestResult.textContent = 'PASS';\n        } catch (error) {\n          els.selfTestResult.dataset.status = 'fail';\n          els.selfTestResult.textContent = `FAIL: ${error.message}`;\n          console.error(error);\n        }\n      }\n\n      function init() {\n        applyPanelWidths();\n        renderWorkspace();\n        renderUnits();\n        renderMarkers();\n        renderInspector();\n        bindEvents();\n        els.timerText.textContent = formatTime(state.elapsed);\n        if (new URLSearchParams(location.search).has('selftest')) {\n          setTimeout(runSelfTest, 60);\n        }\n      }\n\n      init();\n    })();\n  ");
